insert into faq (category,q_en,q_kr,a_en,a_kr,sort) values ('moq','What is the minimum order quantity?','최소 제작 수량은 몇 개인가요?','MOQ depends on the box type and finishing, typically starting around 500–1,000 units. Tell us your product and we''ll confirm the exact minimum.','박스 종류와 후가공에 따라 다르며 보통 500~1,000개부터 시작합니다. 제품을 알려주시면 정확한 최소 수량을 안내해 드립니다.',0);
insert into faq (category,q_en,q_kr,a_en,a_kr,sort) values ('moq','Can I order a small sample first?','먼저 샘플을 받아볼 수 있나요?','Yes. We can produce a sample so you can check structure and print quality before mass production.','네. 양산 전에 구조와 인쇄 품질을 확인할 수 있도록 샘플을 제작해 드립니다.',1);
insert into faq (category,q_en,q_kr,a_en,a_kr,sort) values ('quote','What information do you need for an accurate quote?','정확한 견적을 위해 어떤 정보가 필요한가요?','Box type, dimensions (L×W×H), material, printing, finishing, and quantity. If you''re unsure, just describe your product and we''ll recommend options.','박스 종류, 장폭고(L×W×H), 재질, 인쇄, 후가공, 수량입니다. 잘 모르셔도 제품만 설명해 주시면 옵션을 추천해 드립니다.',2);
insert into faq (category,q_en,q_kr,a_en,a_kr,sort) values ('quote','Why do you ask about my budget?','제작 예산을 왜 물어보나요?','Knowing your budget lets us recommend the best combination of material, printing and finishing within range — not to raise the price.','예산을 알면 그 범위 안에서 최적의 재질·인쇄·후가공 조합을 추천하기 위함이며, 가격을 올리기 위한 것이 아닙니다.',3);
insert into faq (category,q_en,q_kr,a_en,a_kr,sort) values ('design','What is the difference between CMYK and RGB?','CMYK와 RGB의 차이는 무엇인가요?','RGB is for screens; CMYK is for printing. Always provide CMYK files for accurate printed colors — RGB may look different once printed.','RGB는 화면용, CMYK는 인쇄용입니다. 정확한 인쇄 색상을 위해 항상 CMYK 파일을 제공해 주세요. RGB는 인쇄 시 다르게 보일 수 있습니다.',4);
insert into faq (category,q_en,q_kr,a_en,a_kr,sort) values ('design','What is a print-ready design file?','전문 디자인 파일이란 무엇인가요?','A print-ready file is a vector file (AI or PDF) prepared for production — set in CMYK, with outlined fonts, proper cut/fold lines, and at least 3 mm of bleed. Don''t have one? Our designers can create it for you.','인쇄용으로 준비된 벡터 파일(AI 또는 PDF)을 말합니다. CMYK 색상, 윤곽선 처리된 글꼴, 재단·접지선과 3mm 이상의 여백(도련)이 포함되어야 정확하게 제작됩니다. 파일이 없으셔도 저희 디자이너가 만들어 드립니다.',5);
insert into faq (category,q_en,q_kr,a_en,a_kr,sort) values ('design','Can you design the package for us?','패키지 디자인도 함께 맡길 수 있나요?','Yes. Our in-house package designers can develop structure and artwork based on your brand guidelines.','네. 전담 패키지 디자이너가 브랜드 가이드에 맞춰 구조와 디자인을 함께 작업해 드립니다.',6);
insert into faq (category,q_en,q_kr,a_en,a_kr,sort) values ('production','Which paper is safe for food packaging?','식품 포장에 안전한 종이는 무엇인가요?','We use food-safe paper and soy-based ink on all products, so packaging is safe for direct food contact.','전 제품에 식품용 종이와 콩기름 인쇄를 사용하여 식품 포장에 안전합니다.',6);
insert into faq (category,q_en,q_kr,a_en,a_kr,sort) values ('production','How long does custom box production take?','맞춤 박스 제작 기간은 얼마나 걸리나요?','Typically 2–4 weeks after artwork and sample approval, depending on quantity and finishing. We''ll confirm a schedule with your quote.','보통 디자인·샘플 확정 후 수량과 후가공에 따라 2~4주가 소요됩니다. 견적과 함께 일정을 안내해 드립니다.',7);
insert into faq (category,q_en,q_kr,a_en,a_kr,sort) values ('shipping','What shipping options are available for U.S. customers?','미국 고객은 어떤 배송 방식을 선택할 수 있나요?','We support air and sea freight, including FOB terms. We''ll recommend the best option based on volume and timing.','항공·해상 운송을 지원하며 FOB 조건도 가능합니다. 물량과 일정에 맞춰 최적의 방식을 추천해 드립니다.',8);
insert into faq (category,q_en,q_kr,a_en,a_kr,sort) values ('payment','Can I pay via PayPal?','페이팔 결제가 가능한가요?','Yes, PayPal is available for smaller orders. For larger orders we also accept bank transfer (T/T).','네, 소액 주문은 페이팔 결제가 가능합니다. 대량 주문은 계좌 이체(T/T)도 지원합니다.',9);
insert into faq (category,q_en,q_kr,a_en,a_kr,sort) values ('aftercare','What happens if a product defect is found?','제품 불량이 발생하면 어떻게 처리되나요?','Contact us with photos and your item number. We review every claim and arrange remake or compensation for verified defects.','사진과 품번을 보내주시면 모든 건을 검토하여, 확인된 불량은 재제작 또는 보상으로 처리해 드립니다.',10);
insert into glossary (category,term_en,term_kr,desc_en,desc_kr,tags_en,tags_kr,related_portfolio_ids,sort) values ('structure','Folding Carton','단상자','A box made from a single folded paperboard sheet — flat-packable for efficient storage and shipping.','한 장의 판지를 접어 만드는 박스로, 평평하게 접혀 보관·배송이 효율적입니다.',array['Paperboard','Flat-pack']::text[],array['판지','평적']::text[],array['bd-fb-001','bd-rc-001']::text[],0);
insert into glossary (category,term_en,term_kr,desc_en,desc_kr,tags_en,tags_kr,related_portfolio_ids,sort) values ('structure','Rigid Box','싸바리상자','A sturdy box made by wrapping thick chipboard with printed paper — used for premium gift packaging.','두꺼운 판지를 인쇄지로 감싸 만든 견고한 박스로, 프리미엄 선물 패키지에 사용됩니다.',array['Premium','Gift']::text[],array['프리미엄','선물']::text[],array['bd-ts-001','bd-ch-001']::text[],1);
insert into glossary (category,term_en,term_kr,desc_en,desc_kr,tags_en,tags_kr,related_portfolio_ids,sort) values ('paperboard','Kraft Paper','크라프트지','Natural brown paper made from wood pulp — eco-friendly, durable, and popular for a natural look.','목재 펄프로 만든 자연스러운 갈색 종이로, 친환경적이고 튼튼해 내추럴한 이미지에 인기입니다.',array['Eco','Natural']::text[],array['친환경','내추럴']::text[],array['bd-rc-002','bd-pb-001']::text[],2);
insert into glossary (category,term_en,term_kr,desc_en,desc_kr,tags_en,tags_kr,related_portfolio_ids,sort) values ('printing','Spot Color','별색','A pre-mixed ink (e.g. Pantone) used for exact, consistent brand colors that CMYK can''t reproduce reliably.','정확하고 일관된 브랜드 컬러를 위한 사전 혼합 잉크(팬톤 등)로, CMYK로 표현이 어려운 색을 구현합니다.',array['Pantone','Brand color']::text[],array['팬톤','브랜드 컬러']::text[],array['bd-sl-001','bd-ts-001']::text[],3);
insert into glossary (category,term_en,term_kr,desc_en,desc_kr,tags_en,tags_kr,related_portfolio_ids,sort) values ('printing','Soy-based Ink','콩기름 인쇄','Eco-friendly ink made from soybean oil — safe for food packaging and easier to recycle.','콩기름으로 만든 친환경 잉크로, 식품 포장에 안전하고 재활용이 쉽습니다.',array['Eco','Food-safe']::text[],array['친환경','식품 안전']::text[],array['bd-bc-001','bd-db-001']::text[],4);
insert into glossary (category,term_en,term_kr,desc_en,desc_kr,tags_en,tags_kr,related_portfolio_ids,sort) values ('finishing','Foil Stamping','박','A metallic foil (gold, silver, etc.) pressed onto paper with heat for a premium, eye-catching accent.','금·은 등 메탈릭 박을 열로 눌러 찍어 고급스럽고 눈에 띄는 포인트를 만드는 후가공입니다.',array['Premium','Metallic']::text[],array['프리미엄','메탈릭']::text[],array['bd-sl-001','bd-ts-001']::text[],5);
insert into glossary (category,term_en,term_kr,desc_en,desc_kr,tags_en,tags_kr,related_portfolio_ids,sort) values ('finishing','Matte Coating','무광 코팅','A smooth, non-reflective surface coating that protects the print and gives an elegant, soft finish.','반사 없는 매끈한 표면 코팅으로, 인쇄를 보호하고 우아하고 부드러운 외관을 줍니다.',array['Surface','Protection']::text[],array['표면','보호']::text[],array['bd-rc-001','bd-ds-001']::text[],6);
insert into glossary (category,term_en,term_kr,desc_en,desc_kr,tags_en,tags_kr,related_portfolio_ids,sort) values ('structure','Die-cut','도무송','Cutting paper into a custom shape with a steel die — used for windows, tabs, and custom outlines.','목형(칼선)으로 종이를 원하는 모양으로 재단하는 방식으로, 윈도우·탭·커스텀 형태에 사용됩니다.',array['Custom shape']::text[],array['커스텀 형태']::text[],array['bd-st-001','bd-ck-001']::text[],7);
insert into blog (slug,category,title_en,title_kr,summary_en,summary_kr,published_at) values ('how-to-choose-a-cake-box','bakery','How to choose the right cake box for your bakery','베이커리를 위한 케이크 박스 선택 방법','A complete guide to picking the perfect cake box by size, structure and brand needs.','사이즈, 구조, 브랜드 니즈에 맞는 완벽한 케이크 박스 선택 가이드.','2026-05-10') on conflict (slug) do nothing;
insert into blog (slug,category,title_en,title_kr,summary_en,summary_kr,published_at) values ('cmyk-vs-spot-color','printing','CMYK vs Spot Color: what every bakery brand should know','CMYK와 별색, 베이커리 브랜드가 알아야 할 차이','Understand the difference between CMYK and spot color in packaging printing.','패키지 인쇄에서 CMYK와 별색의 차이 이해하기.','2026-05-08') on conflict (slug) do nothing;
insert into blog (slug,category,title_en,title_kr,summary_en,summary_kr,published_at) values ('why-moq-matters','basics','Why minimum order quantity matters in custom packaging','맞춤 패키지에서 최소 제작 수량이 중요한 이유','Why MOQ exists and how to plan your packaging production around it.','최소 제작 수량이 왜 존재하는지, 패키지 생산을 어떻게 계획해야 하는지.','2026-05-05') on conflict (slug) do nothing;
insert into blog (slug,category,title_en,title_kr,summary_en,summary_kr,published_at) values ('soy-ink-for-food-packaging','material','Soy-based ink for food packaging','식품 패키지를 위한 콩기름 인쇄','Why soy-based ink is the eco-friendly choice for food and bakery packaging.','식품 및 베이커리 패키지에 콩기름 인쇄가 친환경 선택인 이유.','2026-05-03') on conflict (slug) do nothing;
insert into guide_section (key,title_en,title_kr,sort) values ('package-types','Package Types','패키지 종류',0);
insert into guide_item (section_id,title_en,title_kr,subtitle,desc_en,desc_kr,tip_en,tip_kr,sort) values ((select id from guide_section where key='package-types' limit 1),'Folding Carton','단상자','Folding Carton','A flat-foldable single-sheet paper box. Economical and versatile.','평평하게 접히는 한 장짜리 종이 박스. 경제적이고 활용도가 높습니다.','','',0);
insert into guide_item (section_id,title_en,title_kr,subtitle,desc_en,desc_kr,tip_en,tip_kr,sort) values ((select id from guide_section where key='package-types' limit 1),'Rigid Box','싸바리상자','Rigid Box','A premium, sturdy wrapped box for high-end packaging.','고급 패키징을 위한 프리미엄 견고한 박스.','','',1);
insert into guide_section (key,title_en,title_kr,sort) values ('box-structures','Box Structures','박스 구조',1);
insert into guide_item (section_id,title_en,title_kr,subtitle,desc_en,desc_kr,tip_en,tip_kr,sort) values ((select id from guide_section where key='box-structures' limit 1),'Tuck Top','덮개형','Tuck Top','A simple folding lid that''s easy to assemble. Great for bakery products.','간단한 접이식 뚜껑으로 조립이 쉬움. 베이커리 제품에 적합.','','',0);
insert into guide_item (section_id,title_en,title_kr,subtitle,desc_en,desc_kr,tip_en,tip_kr,sort) values ((select id from guide_section where key='box-structures' limit 1),'Handle Box','손잡이형','Handle Box','A built-in handle for easy carrying. Ideal for cakes and gift boxes.','간편한 운반을 위한 내장 손잡이. 케이크와 선물 박스에 적합.','','',1);
insert into guide_section (key,title_en,title_kr,sort) values ('paper-materials','Paper & Materials','지류·재질',2);
insert into guide_item (section_id,title_en,title_kr,subtitle,desc_en,desc_kr,tip_en,tip_kr,sort) values ((select id from guide_section where key='paper-materials' limit 1),'Coated Paper (White)','백색 도공지','Coated Paper','Smooth, bright surface ideal for vivid color printing. FSC-certifiable.','선명한 색상 인쇄에 이상적인 매끄럽고 밝은 표면. FSC 인증 가능.','','',0);
insert into guide_item (section_id,title_en,title_kr,subtitle,desc_en,desc_kr,tip_en,tip_kr,sort) values ((select id from guide_section where key='paper-materials' limit 1),'Kraft Paper','크라프트지','Kraft Paper','Natural brown paper with an eco-friendly image. 100% recyclable.','친환경적인 이미지의 자연스러운 갈색 종이. 100% 재활용 가능.','','',1);
insert into guide_section (key,title_en,title_kr,sort) values ('printing','Printing','인쇄',3);
insert into guide_item (section_id,title_en,title_kr,subtitle,desc_en,desc_kr,tip_en,tip_kr,sort) values ((select id from guide_section where key='printing' limit 1),'CMYK (4-Color Process)','CMYK (4도 프로세스)','4-Color Process','Mixes cyan, magenta, yellow and black to reproduce full-color images.','시안·마젠타·옐로우·블랙 4가지 잉크로 모든 색상을 표현하는 기본 컬러 인쇄.','Best for photos and full-color artwork.','사진이나 풀컬러 디자인에 적합합니다.',0);
insert into guide_item (section_id,title_en,title_kr,subtitle,desc_en,desc_kr,tip_en,tip_kr,sort) values ((select id from guide_section where key='printing' limit 1),'Spot Color (Pantone)','별색 (팬톤)','Spot Color','Pre-mixed ink for exact, consistent brand color matching.','정확한 브랜드 컬러 매칭을 위한 사전 혼합 잉크.','Choose this when brand color accuracy is critical.','브랜드 색상 정확도가 중요할 때 선택하세요.',1);
insert into guide_section (key,title_en,title_kr,sort) values ('finishing','Finishing','후가공',4);
insert into guide_item (section_id,title_en,title_kr,subtitle,desc_en,desc_kr,tip_en,tip_kr,sort) values ((select id from guide_section where key='finishing' limit 1),'Matte Coating','무광 코팅','Matte Coating','Smooth, non-reflective surface protection for an elegant look.','매끄럽고 반사 없는 표면 보호. 우아하고 세련된 외관.','','',0);
insert into guide_item (section_id,title_en,title_kr,subtitle,desc_en,desc_kr,tip_en,tip_kr,sort) values ((select id from guide_section where key='finishing' limit 1),'Gold Foil Stamping','금박','Gold Foil Stamping','Metallic gold foil for a premium, eye-catching accent.','프리미엄 포인트를 위한 금색 메탈릭 박.','','',1);
